package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen0Test {

    private static final byte[] TEST_DATA = "Hello World".getBytes();
    private static final int LARGE_SIZE = 1000;
    private static final int SMALL_SIZE = 1;

    @Test
    public void testEncodeBase64_NullInput() {
        assertNull(Base64.encodeBase64(null, false, false, LARGE_SIZE));
    }

    @Test
    public void testEncodeBase64_EmptyInput() {
        byte[] empty = new byte[0];
        byte[] result = Base64.encodeBase64(empty, false, false, LARGE_SIZE);
        assertEquals(0, result.length);
    }

    @Test
    public void testEncodeBase64_MaxResultSizeExceeded() {
        // The encoded length of "Hello World" will definitely be > 1
        try {
            Base64.encodeBase64(TEST_DATA, false, false, SMALL_SIZE);
            fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
        }
    }

    @Test
    public void testEncodeBase64_StandardEncoding() {
        // Standard Base64: "Hello World" -> "SGVsbG8gV29ybGQ="
        byte[] expected = "SGVsbG8gV29ybGQ=".getBytes();
        byte[] result = Base64.encodeBase64(TEST_DATA, false, false, LARGE_SIZE);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testEncodeBase64_UrlSafeEncoding() {
        // Use data that triggers URL safe characters (like '+' or '/')
        // "subjects??" in base64 might contain non-urlsafe chars
        byte[] urlSafeTestData = new byte[]{(byte) 0xfb, (byte) 0xff, (byte) (byte) 0xbf}; 
        // Checking if it runs without error and produces valid length
        byte[] result = Base64.encodeBase64(urlSafeTestData, false, true, LARGE_SIZE);
        assertNotNull(result);
        assertTrue(result.length > 0);
    }

    @Test
    public void testEncodeBase64_ChunkedEncoding() {
        // Chunked encoding uses MIME_CHUNK_SIZE and CHUNK_SEPARATOR
        // We test with a slightly larger array to ensure chunking logic is hit
        byte[] largeTestData = new byte[200];
        for (int i = 0; i < 200; i++) {
            largeTestData[i] = (byte) i;
        }

        // isChunked = true
        byte[] result = Base64.encodeBase64(largeTestData, true, false, 2000);
        assertNotNull(result);
        assertTrue(result.length > largeTestData.length);
    }

    @Test
    public void testEncodeBase64_ChunkedUrlSafe() {
        byte[] largeTestData = new byte[100];
        byte[] result = Base64.encodeBase64(largeTestData, true, true, 2000);
        assertNotNull(result);
    }
}
